using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;
using System.Windows;
using System.Windows.Controls;
namespace Aurora {
public static class OneDriveActions {
    public static string Folder(){return CloudFiles.Roots().FirstOrDefault()??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"OneDrive");}
    static string Installer(){foreach(string root in new[]{Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Microsoft","OneDrive"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"Microsoft OneDrive"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),"Microsoft OneDrive"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"SysWOW64"),Environment.SystemDirectory}){string direct=Path.Combine(root,"OneDriveSetup.exe");if(File.Exists(direct))return direct;if(Directory.Exists(root)&&Path.GetFileName(root).IndexOf("OneDrive",StringComparison.OrdinalIgnoreCase)>=0)foreach(string version in Directory.GetDirectories(root).OrderByDescending(x=>x).Take(30)){string candidate=Path.Combine(version,"OneDriveSetup.exe");if(File.Exists(candidate))return candidate;}}return null;}
    public static string Review(){return CloudFiles.Scan(CloudFiles.Roots()).Description;}
    static string UninstallVerified(){string installer=Installer();if(installer==null)throw new FileNotFoundException(L.T("Instalador do OneDrive não encontrado. A desinstalação não foi iniciada.","OneDrive installer not found. Uninstall was not started."));var signature=Runner.PS("$s=Get-AuthenticodeSignature -LiteralPath "+Runner.QuotePS(installer)+";if($s.Status -ne 'Valid' -or $null -eq $s.SignerCertificate -or $s.SignerCertificate.Subject -notmatch 'Microsoft Corporation'){throw 'OneDrive installer signature is not valid Microsoft software'};'OK'",30000);if(signature.Code!=0)throw new IOException(signature.Output);var result=Runner.Run(installer,"/uninstall",180000);if(result.Code!=0)throw new IOException(result.Output+"\nCode: "+result.Code);return "OK • "+L.T("Desinstalador do OneDrive concluído. O OuO preservou as pastas e não excluiu dados na nuvem.","OneDrive uninstaller completed. OuO preserved folders and did not delete cloud data.");}
    public static string Uninstall(){var scan=CloudFiles.Scan(CloudFiles.Roots());if(scan.Online.Count>0||scan.Issues.Count>0)return scan.Description;return UninstallVerified();}
    public static string Remove(bool download,CancellationToken token,Action<string> stage){
        if(Installer()==null)throw new FileNotFoundException(L.T("Instalador do OneDrive não encontrado.","OneDrive installer not found."));var roots=CloudFiles.Roots();if(download){var review=CloudFiles.Scan(roots,null,token);foreach(var group in review.Online.GroupBy(x=>Path.GetPathRoot(x.Path))){long needed=group.Sum(x=>x.Bytes);if(new DriveInfo(group.Key).AvailableFreeSpace<needed+67108864)throw new IOException(L.T("Espaço livre insuficiente para baixar os arquivos em ","Not enough free space to download files on ")+group.Key);}}
        return CloudFiles.DownloadAndRemove(roots,download,token,stage,null,(file,cancel)=>{var result=Runner.Run(System.Reflection.Assembly.GetExecutingAssembly().Location,"--hydrate-onedrive "+Args.Q(file.Path),600000,null,null,cancel);cancel.ThrowIfCancellationRequested();if(result.Code!=0)throw new IOException(result.Output);},UninstallVerified);
    }
}
public partial class MainWindow {
    int OneDriveChoice(OneDriveScan scan,Action<Window> inspect=null){
        int choice=0;var dialog=new Window{Owner=this,Title="OneDrive",Width=Math.Min(650,SystemParameters.WorkArea.Width-40),SizeToContent=SizeToContent.Height,MaxHeight=SystemParameters.WorkArea.Height-60,WindowStartupLocation=WindowStartupLocation.CenterOwner,WindowStyle=WindowStyle.None,ResizeMode=ResizeMode.NoResize,ShowInTaskbar=false,Background=Surface};
        var content=new StackPanel{Margin=new Thickness(22)};content.Children.Add(Text(T("Arquivos do OneDrive","OneDrive files"),22,Accent));content.Children.Add(new ScrollViewer{Content=Text(scan.Description,14,Ink),MaxHeight=Math.Max(100,SystemParameters.WorkArea.Height-350),VerticalScrollBarVisibility=ScrollBarVisibility.Auto});content.Children.Add(Text(T("Continuar sem baixar mantém os arquivos online na nuvem; eles não terão cópia local confirmada. Para manter tudo no computador, escolha baixar e remover. O download requer conexão, espaço livre e o OneDrive conectado.","Continuing without downloading leaves online-only files in the cloud without a confirmed local copy. To keep everything on this PC, choose download and remove. Downloading requires a connection, free space and signed-in OneDrive."),14,Muted));
        var without=Button(T("Continuar sem baixar","Continue without downloading"),()=>{choice=1;dialog.Close();});var withDownload=Button(T("Baixar e remover OneDrive","Download and remove OneDrive"),()=>{choice=2;dialog.Close();});withDownload.IsEnabled=scan.Issues.Count==0;var cancel=Button(T("Cancelar","Cancel"),()=>dialog.Close());cancel.IsCancel=true;Row(content,without,withDownload,cancel);dialog.Content=new Border{Background=Surface,BorderBrush=Accent,BorderThickness=new Thickness(1),Child=content};if(inspect!=null)inspect(dialog);dialog.ShowDialog();return choice;
    }
    void OneDriveTweak(){
        var card=Card("OneDrive",T("Remova o aplicativo preservando as pastas. Se houver arquivos somente online, escolha continuar sem baixar ou baixar tudo antes de desinstalar.","Remove the app while preserving folders. If files are online-only, choose to continue without downloading or download everything before uninstalling."));
        var state=Text("",13,Muted);card.Children.Add(state);CancellationTokenSource cancellation=null;
        Action<bool> remove=download=>{if(cancellation!=null)return;cancellation=new CancellationTokenSource();var token=cancellation.Token;Work(T("Desinstalar OneDrive","Uninstall OneDrive"),()=>OneDriveActions.Remove(download,token,stage=>ReportStage(stage)),r=>{cancellation.Dispose();cancellation=null;state.Text=r;state.Foreground=CompletionBrush(r);});};
        Row(card,Button(T("Checar arquivos locais","Check local files"),()=>Work(T("Checar OneDrive","Check OneDrive"),()=>OneDriveActions.Review(),r=>{state.Text=r;state.Foreground=OutcomeBrush(r);})),Button(T("Remover OneDrive","Remove OneDrive"),()=>{if(cancellation!=null)return;OneDriveScan found=null;Work(T("Checar arquivos do OneDrive","Check OneDrive files"),()=>{found=CloudFiles.Scan(CloudFiles.Roots());return found.Description;},r=>{state.Text=r;state.Foreground=OutcomeBrush(r);if(found==null)return;if(found.Online.Count>0||found.Issues.Count>0){int choice=OneDriveChoice(found);if(choice!=0)remove(choice==2);}else if(Confirm(T("Desinstalar o OneDrive mantendo os arquivos locais e na nuvem?","Uninstall OneDrive while keeping local and cloud files?")))remove(false);});}),Button(T("Cancelar download","Cancel download"),()=>{if(cancellation!=null)cancellation.Cancel();}));
    }
}
}
